quiz.setup:
const input = require("fs").readFileSync(0, "utf8");
const prices = input.trim().split(",").map((s) => Number(s));
// prices は [ 120, 300, 80, 500, 200 ] のような数値の配列です

// ここに map・filter・find を使ったコードを書く
// ヒント: 配列をカンマ区切りの文字列にするには 配列.join(",")

quiz.answer:
const input = require("fs").readFileSync(0, "utf8").trim();
const prices = input.split(",").map((s) => Number(s));

const withTax = prices.map((p) => Math.round(p * 1.1));
const expensive = prices.filter((p) => p >= 200);
const firstOver100 = prices.find((p) => p > 100);

console.log(withTax.join(","));
console.log(expensive.length > 0 ? expensive.join(",") : "なし");
console.log(firstOver100 !== undefined ? firstOver100 : "なし");

