const lines = require("fs").readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
const target = lines[0].trim();
const users = lines.slice(1).map((line) => {
  const parts = line.split(",");
  return { name: parts[0].trim(), age: Number(parts[1]) };
});
// users は [ { name: "佐藤", age: 28 }, ... ] のようなオブジェクトの配列です

// ここに find を使ったコードを書く

quiz.answer:
const lines = require("fs").readFileSync(0, "utf8").split("\n").filter((l) => l.trim() !== "");
const target = lines[0].trim();
const users = lines.slice(1).map((line) => {
  const [name, age] = line.split(",");
  return { name: name.trim(), age: Number(age) };
});

const found = users.find((u) => u.name === target);
if (found) {
  console.log(`${found.name}は${found.age}歳`);
} else {
  console.log(`${target}は見つかりません`);
}

